const t={remoteControl:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Отправляйте команды на экран FilaMind, установленный на принтере."}},status:{ready:{t:0,b:{t:2,i:[{t:3}],s:"Командная шина подключена"}},down:{t:0,b:{t:2,i:[{t:3}],s:"Подключение к командной шине…"}}},show:{title:{t:0,b:{t:2,i:[{t:3}],s:"Показать на экране"}},status:{t:0,b:{t:2,i:[{t:3}],s:"Состояние"}},control:{t:0,b:{t:2,i:[{t:3}],s:"Управление"}},settings:{t:0,b:{t:2,i:[{t:3}],s:"Настройки"}}},locate:{title:{t:0,b:{t:2,i:[{t:3}],s:"Найти экран"}},hint:{t:0,b:{t:2,i:[{t:3}],s:"Подсветите экран миганием, чтобы понять, какому принтеру он принадлежит."}},button:{t:0,b:{t:2,i:[{t:3}],s:"Найти экран"}}},message:{title:{t:0,b:{t:2,i:[{t:3}],s:"Отправить сообщение"}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:"Введите короткое сообщение для показа на экране…"}},level:{t:0,b:{t:2,i:[{t:3}],s:"Уровень"}},info:{t:0,b:{t:2,i:[{t:3}],s:"Информация"}},warn:{t:0,b:{t:2,i:[{t:3}],s:"Предупреждение"}},send:{t:0,b:{t:2,i:[{t:3}],s:"Отправить"}}},sent:{t:0,b:{t:2,i:[{t:3}],s:"Отправлено"}},help:{button:{t:0,b:{t:2,i:[{t:3}],s:"Справка"}},title:{t:0,b:{t:2,i:[{t:3}],s:"Удалённое управление — руководство"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Закрыть"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Что это даёт"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Эта панель управляет сенсорным экраном FilaMind на принтере прямо отсюда: переключает его вкладку, показывает короткое сообщение или подсвечивает экран миганием, чтобы понять, какой это принтер. Это только подсказки для дисплея — они никогда не приводят принтер в движение и не меняют настройки."}}},commands:{title:{t:0,b:{t:2,i:[{t:3}],s:"Команды"}},body:{t:0,b:{t:2,i:[{t:3}],s:"«Показать» переключает экран на вкладку «Состояние», «Управление» или «Настройки». «Найти» подсвечивает экран миганием на несколько секунд. «Сообщение» показывает короткую заметку (информация или предупреждение). Команды доходят до любого экрана FilaMind на этом принтере; пока командная шина ещё подключается, ничего не отправляется."}}}}},requiresScreen:{t:0,b:{t:2,i:[{t:3}],s:"Эти элементы управляют экраном FilaMind на принтере. Установите FilaMind 3D на этот принтер, чтобы использовать их."}}}};export{t as default};
